function decodeEntities(s) {
  return s
    .replace(/&nbsp;|&#160;|&#xa0;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/ /g, ' ');
}

function extractText(payload) {
  if (payload?.body?.data) {
    const text = Buffer.from(payload.body.data, 'base64url').toString('utf-8');
    if (text.trim()) return text;
  }
  function searchParts(parts = []) {
    for (const part of parts) {
      if (part.mimeType === 'text/plain' && part.body?.data)
        return Buffer.from(part.body.data, 'base64url').toString('utf-8');
      if (part.parts) {
        const found = searchParts(part.parts);
        if (found) return found;
      }
    }
    for (const part of parts) {
      if (part.mimeType === 'text/html' && part.body?.data) {
        const html = Buffer.from(part.body.data, 'base64url').toString('utf-8');
        return html.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      }
    }
    return null;
  }
  return searchParts(payload?.parts) || $json.snippet || "";
}

const emailText = decodeEntities(extractText($json.payload)).replace(/\s+/g, ' ');

const orderId = emailText.match(/commande\s*[:*]*\s*([0-9]{3}-[0-9]{7}-[0-9]{7})/i)?.[1] || "";

const shipDateMatch = emailText.match(/Exp.?dier\s+avant\s+le[^0-9]*(\d{2}\/\d{2}\/\d{4})/i);
const rawDate = shipDateMatch ? shipDateMatch[1] : "Non trouvé";

const blocks = emailText.split(/Produit\s*[:*]*/i).slice(1);
const finalBlocks = blocks.length > 0 ? blocks : emailText.split(/SKU\s*[:*]*/i).slice(1);

const items = finalBlocks.map(block => {
  const sku = block.match(/SKU\s*[*]?\s*:?\s*[*]?\s*([A-Za-z0-9][A-Za-z0-9._-]*)/i)?.[1] || "";
  const quantity = parseInt(block.match(/Quantit[eé]\s*[*]?\s*:?\s*[*]?\s*(\d+)/i)?.[1]) || 1;
  return { sku, quantity };
});

return [{ json: { source: "gmail", orderId, date_limite_expedition: rawDate, notes: `Commande Amazon ${orderId}`, items } }];

const inputData = $input.first().json;
let formattedDate = null;
if (inputData.date_limite_expedition && inputData.date_limite_expedition !== "Non trouvé") {
  const parts = inputData.date_limite_expedition.split('/');
  if (parts.length === 3) {
    formattedDate = `${parts[2]}-${parts[1]}-${parts[0]}`;
  }
}
const itemsForStockr = inputData.items
  .filter(item => item.sku || item.quantity > 0)
  .map(item => {
    const result = { quantity: parseInt(item.quantity) || 1 };
    if (item.sku) {
      // SKU Amazon -> supplierRef : le backend résout le vrai nom de la variante
      result.supplierRef = item.sku;
    } else {
      result.variantName = 'Article non identifié';
    }
    return result;
  });
return {
  customerName: "Amazon Order",
  customerEmail: inputData.customerEmail || "client@example.com",
  shippingDate: formattedDate,
  notes: inputData.notes,
  source: "amazon",
  items: itemsForStockr
};
